        #[test]
        fn test_morpheme_choice_deterministic() {
            // Choice is deterministic based on array contents
            let result = run_sigil(
                r#"
                rite main() -> i64 {
                    [10, 20, 30] |χ
                }
            "#,
            );
            // Result should be one of 10, 20, or 30
            let val = result.unwrap();
            assert!(val == 10 || val == 20 || val == 30);
        }

